var TECH=[["Input validation", "Allowlisting expected shapes at every trust boundary."], ["Parameterized queries", "Separating code from data to eliminate SQL injection."], ["Output encoding", "Context-aware escaping defeating XSS in HTML, JS and URLs."], ["Least privilege", "Granting each component only the access it needs."], ["Defense in depth", "Layered controls so one failure never means total compromise."], ["Secrets management", "Vaults and short-lived credentials replacing hardcoded keys."], ["Dependency scanning", "Continuously matching manifests against vulnerability databases."], ["Sandboxing", "Running untrusted code with minimal capabilities."], ["Security headers", "HSTS, CSP and friends hardening every HTTP response."], ["Incident response drills", "Practicing detection, containment and recovery before breaches."]];
